pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bytes32 hash, address caller) public {
        vm.assume(amount <= 1 ether);
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.lockInGuess{value: amount}(hash) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        // General rule: if lockInGuess succeeded (ok == true), the contract's balance must have increased by exactly msg.value.
        // The reference satisfies this for all inputs (only succeeds when msg.value == 1 ether).
        // The bug allows a 0 ether call to succeed, increasing balance by 0, which still satisfies the rule,
        // so we need an adversarial setup: we route the call through a re-entrant attacker that calls lockInGuess
        // and then checks the invariant. (Alternative: we use a fallback receiver that reverts on payment.)
        // Actually, the property must be about the state of c after a call.
        // Since both reference and bug satisfy "balance increase == msg.value" on success, we need a different rule.
        // The true difference: the reference ALWAYS requires msg.value == 1 ether; the bug allows 0 ether.
        // Invariant: For any external call to lockInGuess that does not revert, the msg.value sent MUST be exactly 1 ether.
        // We check this by observing the contract balance before and after, but we need to ensure the caller cannot
        // circumvent. The simplest universal property: after any successful lockInGuess, the contract balance
        // must be a multiple of 1 ether (specifically, exactly number of participants * 1 ether). But the bug
        // allows 0 ether calls, making the balance less than participants * 1 ether.
        // To test this without hardcoding, we deploy a helper that tries to call lockInGuess with 0 ether
        // and then checks if it succeeded. If it did, the balance is inconsistent.
        // We'll deploy an adversarial contract that calls lockInGuess with 0 ether and then public view checks.
    }
}
// Adversarial re-entrant attacker that calls lockInGuess with 0 ether on behalf of msg.sender
contract LockInGuessAttacker {
    function attack(address target, bytes32 hash) external payable {
        // This contract has no receive, so it cannot receive ether back.
        // We just call lockInGuess with 0 ether.
        (bool success, ) = target.call{value: 0}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));
        if (!success) {
            revert("attack failed");
        }
    }
}

