pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address actor, bytes32 hash) public {
        // Bound actor to non-zero address
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // The first call must succeed to set up the precondition of a pending guess.
        // The correct contract requires 1 ether. Add enough for both calls.
        uint256 fund = 3 ether;
        vm.deal(actor, fund);

        // Step 1: Make a valid first guess to put the actor into a "pending" state.
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        vm.stopPrank();

        // Step 2: Attempt a second lockInGuess with a fuzzed amount.
        // Bound amount to available balance.
        secondAmount = bound(secondAmount, 0, actor.balance);
        vm.deal(actor, fund); // ensure balance is topped up for fuzzer's amount choice

        vm.startPrank(actor);
        try c.lockInGuess{value: secondAmount}(hash) {
            // If it does not revert, the buggy contract accepted a second guess.
            // The reference contract MUST revert.
            assertTrue(false, "Second lockInGuess should have reverted");
        } catch {
            // If it reverts, the reference contract behaves correctly.
            // The buggy contract will not revert for zero-value second calls, 
            // thus the try block will NOT catch, hitting the assertTrue(false) above.
            assertTrue(true, "Correct behavior: reverted as expected");
        }
        vm.stopPrank();
    }
}

