import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash) public {
        // Provide enough funds for both lockInGuess and potentially settle reward
        vm.deal(address(this), 3 ether);
        // Call lockInGuess to lock a guess
        c.lockInGuess{value: 1 ether}(guessHash);

        // Attempt to settle in the same transaction/block.
        // On correct: settle() should revert because block.number is not > guesses[msg.sender].block (set to block.number + 1)
        // On buggy:  settle() should succeed because guesses[msg.sender].block == block.number, and block.number > block.number is false?
        // Wait - on buggy, block.number > guesses[msg.sender].block requires block.number > block.number, which is false. So buggy would also revert?
        // Actually, in lockInGuess, guesses[msg.sender].block = block.number. In settle, require(block.number > guesses[msg.sender].block) -> block.number > block.number -> false, revert.
        // So immediate settle would revert on both. The difference only manifests on a subsequent block.

        // Therefore, advance block by 1 to observe difference.
        vm.roll(block.number + 1);

        // On correct: guesses[msg.sender].block was block.number(Lock) + 1, so current block.number == block.number(Lock) + 1, which is NOT > block.number(Lock)+1 => revert.
        // Wait, careful:
        // Let B = block.number at lockInGuess.
        // Correct: guesses[msg.sender].block = B+1.
        // After vm.roll(B+1), current block.number = B+1.
        // require(block.number > guesses[msg.sender].block) => B+1 > B+1 => false, revert.
        // Buggy: guesses[msg.sender].block = B.
        // After vm.roll(B+1), current block.number = B+1.
        // require(block.number > guesses[msg.sender].block) => B+1 > B => true, proceed.

        // Also need to ensure answer matches guess so that transfer is attempted, else settle doesn't test anything about balances.
        // The fuzzer supplies guessHash. We need to ensure it equals the answer derived from blockhash(B) on buggy.
        // But we cannot predict blockhash(B) without knowing B. We can compute it within the test.
        // However, the test is written such that we assert a property that holds regardless of whether guess matches.
        // We need a general rule that reference satisfies for all inputs and bug breaks for some input.
        // Rule: After lockInGuess and a roll of 1 block, if the guess matches the answer, a successful settle should increase address(this).balance by a certain amount?
        // Not exactly. The property should be about revert or success behavior of settle.

        // The bug: in buggy version, settle can succeed earlier (one block after lock). But wait, it still requires block.number > guesses[msg.sender].block.
        // So on correct, settle can succeed 2 blocks after lock. On buggy, 1 block after lock.
        // Universal property: "settle() called exactly 1 block after lockInGuess must revert".
        // This holds for correct, but bug violates it for input where guess matches.
        // But if guess doesn't match, settle on buggy will still be called (no revert from the require), but won't transfer, so it "succeeds" without transfer.
        // To distinguish, we need settle() to revert on correct but not on buggy. That requires the condition block.number > guesses[msg.sender].block to evaluate differently.
        // As analyzed: at block B+1, correct has block requirement B+1 > B+1 (false), buggy has B+1 > B (true). So correct reverts on that require, buggy passes.
        // So the revert condition itself is the property. We don't need guess to match; we just need to call settle() and observe revert.
        // But there is another require in settle: require(guesses[msg.sender].block != 0). After lockInGuess, it's non-zero. After a failed settle, if we had a previous guess... but we call lockInGuess exactly once per test.
        // So at block B+1 on correct, settle reverts due to block.number > guesses[msg.sender].block.
        // On buggy, it proceeds.

        // Therefore, we can assert that settle() at block B+1 MUST revert.
        // This is true for correct for all guesses, and false for buggy for all guesses.
        // So the fuzzed guessHash is irrelevant to the property (but serves as fuzz param to satisfy the requirement).
        // We can use try/catch to capture revert.

        bool reverted = false;
        try c.settle() {
            // if success, reverted stays false
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}

