pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Fuzz caller address using a fresh address to avoid conflicts
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(hash)))));
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Provide 1 ether to actor and record current block
        vm.deal(actor, 1 ether);
        uint256 blockBefore = block.number;

        // Prank as actor and lock in guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Now attempt to settle in the exact same block
        vm.prank(actor);
        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }

        // General rule: settling in the same block as lockInGuess must revert.
        // Since we are still in the same block, settled should be false for reference,
        // but the mutant sets block to block.number, allowing settle to succeed.
        assertTrue(!settled);
    }
}

