pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash) public {
        // Admissible: guessHash can be anything, but we need the caller to lock in and then settle after the required block.
        address caller = address(0xbeef);
        vm.deal(caller, 2 ether);
        vm.deal(address(c), 1 ether); // constructor requirement

        // Lock in guess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance block so settle is possible
        vm.roll(block.number + 2);

        uint balBefore = caller.balance;
        vm.prank(caller);
        try c.settle() {} catch {}
        uint balAfter = caller.balance;

        // Compute whether the guess was actually correct
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 2)));
        bool correct = (guessHash == answer);

        // Rule: a caller who guesses wrong (guessHash != answer) must NOT receive 2 ether.
        // They may receive exactly 0 extra ether (or lose gas, but their balance should not increase by 2 ether).
        if (!correct) {
            assertTrue(balAfter - balBefore < 2 ether);
        } else {
            // If correct, they may or may not receive 2 ether depending on contract balance etc.,
            // but the property we test is only about wrong guesses; we must still make the assertion valid for all inputs.
            // We just need a single assertion that holds in the reference and fails in the mutant for some input.
            // The fuzzer will find a wrong guess (guessHash != answer) and the reference passes the assertion (bal increase < 2 eth),
            // while the mutant fails it (bal increase == 2 eth).
            // For correct guesses, the assertion below is trivially true because the if branch wasn't taken,
            // but we still need an assertion that evaluates for all fuzz inputs.
            // To satisfy the requirement of a single assertTrue that is universal, we embed the check inside a conditional
            // but we cannot do that because assertTrue must always be evaluated. So we restructure:
            // assertTrue(!(!correct) || (balAfter - balBefore < 2 ether));
        }
        // Universal assertion: if the guess is wrong, the caller's balance increase is less than 2 ether.
        assertTrue(!(!correct) || (balAfter - balBefore < 2 ether));
    }
}

