pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockAdvance) public {
        // Bound blockAdvance so block.number can advance past the lock-in block
        blockAdvance = bound(blockAdvance, 1, 1000);
        // Fund the contract with 2 ether so the prize can be paid
        vm.deal(address(c), 2 ether);
        // Prank as a user (address(this)) to lock in a guess with 1 ether
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.lockInGuess{value: 1 ether}(guess);
        // Advance the block number so settle can be called
        vm.roll(block.number + blockAdvance);
        // Record balance before settle
        uint256 balanceBefore = address(this).balance;
        // Call settle
        vm.prank(address(this));
        c.settle();
        uint256 balanceAfter = address(this).balance;
        // Compute the correct answer
        uint256 lockBlock = block.number - blockAdvance;
        bytes32 correctAnswer = keccak256(abi.encodePacked(blockhash(lockBlock)));
        // If the guess was NOT correct, the caller must not have gained 2 ether
        bool gainedTwoEther = (balanceAfter - balanceBefore) == 2 ether;
        if (guess != correctAnswer) {
            assertTrue(!gainedTwoEther);
        } else {
            // In the reference contract, a correct guess pays 2 ether; the mutant pays nothing on a correct guess.
            // We don't need a separate assertion for that; the invariant above already fails on the mutant for a wrong guess.
            assertTrue(gainedTwoEther);
        }
    }
}
